// Dashboard.jsx
import React, { useContext, useEffect, useState } from "react";
import { AuthContext } from "../App";
import API from "../api";

// Chart imports
import { Pie, Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
  Legend,
  CategoryScale,
  LinearScale,
  BarElement,
  Title
} from "chart.js";

// register chart components
ChartJS.register(ArcElement, Tooltip, Legend, CategoryScale, LinearScale, BarElement, Title);

/*
  Dashboard:
  - Loads tasks from /tasks
  - Shows create form (minimal)
  - Shows two charts:
      * Pie: distribution of task progress states
      * Bar: tasks due per day for upcoming 7 days
  - Inline comments explain logic
*/

export default function Dashboard() {
  const { auth, logout } = useContext(AuthContext);
  const [tasks, setTasks] = useState([]);
  const [title, setTitle] = useState("");
  const [desc, setDesc] = useState("");
  const [due, setDue] = useState("");

  // fetch tasks from server
  const loadTasks = async () => {
    try {
      const res = await API.get("/tasks");
      if (res.data.success) setTasks(res.data.tasks);
    } catch (err) {
      console.error("Failed to load tasks", err);
    }
  };

  useEffect(() => { loadTasks(); }, []);

  // create a task (must use auth.userId)
  const createTask = async (e) => {
    e.preventDefault();
    try {
      await API.post("/tasks", {
        userId: auth.userId,
        title,
        description: desc,
        dueDate: due || null
      });
      setTitle(""); setDesc(""); setDue("");
      loadTasks();
    } catch (err) {
      alert(err.response?.data?.message || "Create failed");
    }
  };

  const update = async (id, progress) => {
    try{
      await API.put(`/tasks/${id}`, { progress });
      loadTasks();
    }catch(err){
      alert(err.response?.data?.message || "Update failed");
    }
  };

  const remove = async (id) => {
    if(!window.confirm("Delete task?")) return;
    try{
      await API.delete(`/tasks/${id}`);
      loadTasks();
    }catch(err){
      alert(err.response?.data?.message || "Delete failed");
    }
  };

  // ========== Chart data preparation ==========

  // 1) Pie chart - count tasks per progress state
  const progressCounts = tasks.reduce((acc, t) => {
    acc[t.progress] = (acc[t.progress] || 0) + 1;
    return acc;
  }, {});

  const pieData = {
    labels: ["Not started", "In progress", "Completed"],
    datasets: [{
      data: [
        progressCounts["not-started"] || 0,
        progressCounts["in-progress"] || 0,
        progressCounts["completed"] || 0
      ],
      backgroundColor: ["#fde68a", "#60a5fa", "#34d399"], // warm amber, soft blue, green
      hoverOffset: 6
    }]
  };

  // 2) Bar chart - tasks due per day for next 7 days
  const days = Array.from({length:7}).map((_,i=>{
    const d = new Date();
    d.setDate(d.getDate()+i);
    return d;
  }));

  const dayLabels = days.map(d => d.toLocaleDateString(undefined, {month:'short', day:'numeric'}));
  const tasksByDay = days.map(d => {
    const dayStart = new Date(d); dayStart.setHours(0,0,0,0);
    const dayEnd = new Date(d); dayEnd.setHours(23,59,59,999);
    return tasks.filter(t => {
      if(!t.dueDate) return false;
      const dd = new Date(t.dueDate);
      return dd >= dayStart && dd <= dayEnd;
    }).length;
  });

  const barData = {
    labels: dayLabels,
    datasets: [{
      label: 'Tasks due',
      data: tasksByDay,
      backgroundColor: "#93c5fd",
    }]
  };

  return (
    <div className="app-container">
      <div className="header">
        <div>
          <h2 className="h-title">Dashboard</h2>
          <div className="h-sub">Role: {auth.role} • ID: {String(auth.userId).slice(0,8)}</div>
        </div>
        <div className="row">
          <button className="btn" onClick={loadTasks}>Refresh</button>
          <button className="btn btn-danger" onClick={logout}>Logout</button>
        </div>
      </div>

      <div className="stats">
        <div className="stat-card">
          <div style={{fontSize:14, color:"#64748b"}}>Total tasks</div>
          <div style={{fontWeight:700, fontSize:22}}>{tasks.length}</div>
          <div className="small">Tasks created by you or assigned students</div>
        </div>

        <div className="stat-card">
          <div style={{fontSize:14, color:"#64748b"}}>Completed</div>
          <div style={{fontWeight:700, fontSize:22}}>{progressCounts["completed"] || 0}</div>
          <div className="small">Keep it up — aim for smaller sprints</div>
        </div>

        <div className="stat-card">
          <div style={{fontSize:14, color:"#64748b"}}>In Progress</div>
          <div style={{fontWeight:700, fontSize:22}}>{progressCounts["in-progress"] || 0}</div>
          <div className="small">Tasks currently in motion</div>
        </div>
      </div>

      {/* Charts area */}
      <div style={{display:"flex", gap:18, marginTop:18, alignItems:"stretch", flexWrap:"wrap"}}>
        <div style={{flex:"1 1 320px", minWidth:300, padding:12, borderRadius:10, background:"white", border:"1px solid #eef2f3"}}>
          <div style={{display:"flex", justifyContent:"space-between", alignItems:"center"}}>
            <div style={{fontWeight:700}}>Progress Distribution</div>
            <div className="small">Overview</div>
          </div>
          <div style={{height:240, paddingTop:8}}>
            <Pie data={pieData} />
          </div>
        </div>

        <div style={{flex:"1 1 420px", minWidth:320, padding:12, borderRadius:10, background:"white", border:"1px solid #eef2f3"}}>
          <div style={{display:"flex", justifyContent:"space-between", alignItems:"center"}}>
            <div style={{fontWeight:700}}>Upcoming Due Tasks (7 days)</div>
            <div className="small">Timeline</div>
          </div>
          <div style={{height:240, paddingTop:8}}>
            <Bar data={barData} options={{
              plugins:{ title:{ display:false }, legend:{ display:false } },
              scales:{ y: { beginAtZero:true, ticks:{precision:0} } }
            }} />
          </div>
        </div>
      </div>

      {/* create task + list */}
      <div style={{display:"flex", gap:18, marginTop:20, alignItems:"flex-start", flexWrap:"wrap"}}>
        <div style={{flex:"1 1 320px"}}>
          <h3 style={{marginTop:0}}>Create Task</h3>
          <form className="form" onSubmit={createTask}>
            <input className="input" placeholder="Title" value={title} onChange={e=>setTitle(e.target.value)} required />
            <input className="input" placeholder="Description" value={desc} onChange={e=>setDesc(e.target.value)} />
            <input className="input" type="date" value={due} onChange={e=>setDue(e.target.value)} />
            <div style={{display:"flex", gap:8}}>
              <button className="btn btn-primary" type="submit">Create</button>
              <button type="button" className="btn" onClick={()=>{ setTitle(""); setDesc(""); setDue(""); }}>Reset</button>
            </div>
          </form>
        </div>

        <div style={{flex:"1 1 420px"}}>
          <h3 style={{marginTop:0}}>Tasks</h3>
          <div className="tasks">
            {tasks.length === 0 && <div className="small">No tasks yet</div>}
            {tasks.map(t => (
              <div className="task-card" key={t._id}>
                <div style={{maxWidth:"70%"}}>
                  <div style={{fontWeight:700}}>{t.title}</div>
                  <div className="small">{t.description}</div>
                  <div className="small">Due: {t.dueDate ? new Date(t.dueDate).toLocaleDateString() : "—"}</div>
                </div>

                <div style={{display:"flex", flexDirection:"column", gap:8, alignItems:"flex-end"}}>
                  <select className="input" value={t.progress} onChange={(e)=>update(t._id, e.target.value)}>
                    <option value="not-started">Not started</option>
                    <option value="in-progress">In Progress</option>
                    <option value="completed">Completed</option>
                  </select>
                  <div className="row">
                    <button className="btn btn-danger" onClick={()=>remove(t._id)}>Delete</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
